<span class="line"><span style="color:#268BD2;">    COUNT</span><span style="color:#839496;">(</span><span style="color:#859900;">CASE</span><span style="color:#859900;"> WHEN</span><span style="color:#839496;"> gender </span><span style="color:#859900;">=</span><span style="color:#2AA198;"> &#39;F&#39;</span><span style="color:#859900;"> THEN</span><span style="color:#D33682;"> 1</span><span style="color:#859900;"> END</span><span style="color:#839496;">) </span><span style="color:#859900;">AS</span><span style="color:#839496;"> female_count</span></span>
