<span class="line"><span style="color:#839496;">  cardID  </span><span style="color:#93A1A1;font-weight:bold;">CHAR</span><span style="color:#839496;">(</span><span style="color:#D33682;">19</span><span style="color:#839496;">)  </span><span style="color:#859900;">NOT NULL</span><span style="color:#839496;">,</span></span>
