<span class="line"><span style="color:#93A1A1;font-weight:bold;">      CONSTRAINT</span><span style="color:#839496;">  DF_IsReportLoss </span><span style="color:#93A1A1;font-weight:bold;">DEFAULT</span><span style="color:#839496;">(</span><span style="color:#D33682;">0</span><span style="color:#839496;">) </span><span style="color:#859900;">FOR</span><span style="color:#839496;"> IsReportLoss,</span></span>
